import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmAddCurso = ({ onClose }) => {
  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
  });

  const handleChange = (e) => {
    setCurso({ ...curso, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const resposta = await fetch("http://localhost:5000/cursos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(curso),
      });

      if (resposta.ok) {
        alert("Curso cadastrado com sucesso!");
        onClose(); // Fecha o modal/formulário
      } else {
        alert("Erro ao cadastrar curso.");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-center mt-4">
        <form
          className="bg-white p-4 rounded shadow"
          style={{ width: "400px" }}
          onSubmit={handleSubmit}
        >
          <input
            type="text"
            name="nome"
            className="form-control mb-3"
            placeholder="Nome"
            value={curso.nome}
            onChange={handleChange}
            required
          />

          <select
            name="nivel"
            className="form-control mb-3"
            value={curso.nivel}
            onChange={handleChange}
            required
          >
            <option value="">Nível</option>
            <option value="Básico">Básico</option>
            <option value="Intermediário">Intermediário</option>
            <option value="Avançado">Avançado</option>
          </select>

          <select
            name="periodo"
            className="form-control mb-3"
            value={curso.periodo}
            onChange={handleChange}
            required
          >
            <option value="">Período</option>
            <option value="Matutino">Matutino</option>
            <option value="Vespertino">Vespertino</option>
            <option value="Noturno">Noturno</option>
          </select>

          <select
            name="area"
            className="form-control mb-3"
            value={curso.area}
            onChange={handleChange}
            required
          >
            <option value="">Área</option>
            <option value="Exatas">Exatas</option>
            <option value="Humanas">Humanas</option>
            <option value="Biológicas">Biológicas</option>
          </select>

          <div className="d-flex justify-content-between">
            <button type="button" className="btn btn-danger" onClick={onClose}>
              Cancelar
            </button>
            <button type="submit" className="btn btn-primary">
              Salvar
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdmAddCurso;
